import{_ as e,c as t,o as r,a2 as i}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"聯絡我們","description":"透過郵件取得 qDiff 協助，以及怎樣描述問題能更快得到回覆。","frontmatter":{"title":"聯絡我們","description":"透過郵件取得 qDiff 協助，以及怎樣描述問題能更快得到回覆。"},"headers":[],"relativePath":"zh-TW/guide/support.md","filePath":"zh-TW/guide/support.md","lastUpdated":1794296122000}'),o={name:"zh-TW/guide/support.md"};function l(p,a,f,n,h,s){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="聯絡我們" tabindex="-1">聯絡我們 <a class="header-anchor" href="#聯絡我們" aria-label="Permalink to &quot;聯絡我們&quot;">​</a></h1><p>看不懂的地方、打不開的檔案、對下一版的想法 —— 每一封郵件我們都會看。</p><p><strong>信箱：</strong> <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a></p><p>中文或英文都可以，日文、德文、西班牙文、法文也歡迎。</p><h2 id="怎樣描述-回覆更快" tabindex="-1">怎樣描述，回覆更快 <a class="header-anchor" href="#怎樣描述-回覆更快" aria-label="Permalink to &quot;怎樣描述，回覆更快&quot;">​</a></h2><ul><li>你的 macOS 版本和機型。</li><li>qDiff 版本（在 App 選單裡打開「關於 qDiff」）。</li><li>當時在比較什麼，原本期望看到什麼。</li><li>如果問題看得見，附一張截圖。</li></ul><p>不方便分享的檔案就不用發，一段描述或裁過的截圖通常已經夠了。</p><h2 id="寫信之前" tabindex="-1">寫信之前 <a class="header-anchor" href="#寫信之前" aria-label="Permalink to &quot;寫信之前&quot;">​</a></h2><p><a href="./faq.html">常見問題</a>收了最常被問到的幾件事，<a href="./introduction.html">認識 qDiff</a> 裡有第一次比較的完整過程。關心隱私的話，<a href="./../privacy/">隱私政策</a>寫清楚了 qDiff 會讀什麼、不會讀什麼。</p><h2 id="關於購買與退款" tabindex="-1">關於購買與退款 <a class="header-anchor" href="#關於購買與退款" aria-label="Permalink to &quot;關於購買與退款&quot;">​</a></h2><p>購買和退款由 Mac App Store 與你的 Apple ID 處理。帳單問題找 Apple 支援最快； 在 qDiff 裡恢復購買的方法見<a href="./faq.html">常見問題</a>。</p>',11)])])}const u=e(o,[["render",l]]);export{c as __pageData,u as default};
